297	   297	     * statement bound them to kept, listed after into's claims in the order they were added); from's statements become
298	   298	     * into's (into's last statement stays their last; having none, from's last becomes it); from's name and aliases
299	   299	     * become into's aliases; from's patrons are added to into's and anyone naming from names into instead (never
300	   300	     * themselves, no repeats); from's pool memberships and closed-period figures move to into (added to into's own where
301	   301	     * into has one), and so do from's opening balances, plans and crews (a crew from leads is led by into). from's holds, watchers, grades and contact are dropped, and from leaves the sheet.
302	   302	     */
303	   303	    public void merge(String sheetId, long from, long into) {
304	   304	        for (Long claim : jdbc.queryForList("SELECT id FROM claim WHERE person_id = ? ORDER BY listed, id", Long.class, from)) {
305	   305	            jdbc.update("UPDATE claim SET person_id = ?, listed = "
306	   306	                    + "(SELECT COALESCE(MAX(listed), 0) + 1 FROM claim WHERE sheet_id = ?) WHERE id = ?", into, sheetId, claim);
307	   307	        }
308	   308	        String name = jdbc.queryForObject("SELECT name FROM person WHERE id = ?", String.class, from);
309	   309	        jdbc.update("UPDATE person_alias SET person_id = ? WHERE person_id = ?", into, from);
310	   310	        for (Long patron : jdbc.queryForList("SELECT patron_id FROM person_patron WHERE person_id = ? ORDER BY named", Long.class, from)) {
311	   311	            linkPatron(into, patron);
312	   312	        }
313	   313	        for (Long person : jdbc.queryForList("SELECT person_id FROM person_patron WHERE patron_id = ?", Long.class, from)) {
314	   314	            linkPatron(person, into);
315	   315	        }
316	   316	        jdbc.update("DELETE FROM person_patron WHERE person_id = ? OR patron_id = ?", from, from);
317	   317	        for (Map<String, Object> m : jdbc.queryForList("SELECT pool_name, share FROM pool_member WHERE sheet_id = ? AND person_id = ?",
318	   318	                sheetId, from)) {
319	   319	            if (jdbc.update("UPDATE pool_member SET share = share + ? WHERE sheet_id = ? AND pool_name = ? AND person_id = ?",
320	   320	                    m.get("share"), sheetId, m.get("pool_name"), into) == 0) {
321	   321	                jdbc.update("UPDATE pool_member SET person_id = ? WHERE sheet_id = ? AND pool_name = ? AND person_id = ?",
