120	    // Only a steward (by the role the sheet gives them, not one delegated to them) delegates. The user name must not be
121	    // blank; a blank from-date is the sheet's today, a blank to-date the from-date; a to-date before the from-date is refused.
122	    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody DelegateRequest body,
123	            ServerHttpConnection connection, Settings settings, Sheets sheets, Out<Delegation> delegation)
124	            throws InvalidSettingException {
125	        String id = sheetId.trim();
126	        String by = Audit.user(connection).trim();
127	        if (!Settings.STEWARD.equals(settings.givenRole(id, by))) {
128	            throw new InvalidSettingException("Only a steward can delegate the steward role.");
129	        }
130	        String user = body == null || body.user() == null ? "" : body.user().trim();
131	        if (user.isEmpty()) {
132	            throw new InvalidSettingException("A user name is needed.");
133	        }
134	        LocalDate from = parse(body.from());
135	        if (from == null) {
136	            from = sheets.today(id);
137	        }
138	        LocalDate to = parse(body.to());
139	        if (to == null) {
140	            to = from;
141	        }
142	        if (to.isBefore(from)) {
143	            throw new InvalidSettingException("The to-date is before the from-date.");
144	        }
145	        delegation.set(new Delegation(id, user, from, to, by));
146	    }
