148	    private static LocalDate parse(String value) throws InvalidSettingException {
149	        String raw = value == null ? "" : value.trim();
150	        if (raw.isEmpty()) {
151	            return null;
152	        }
153	        try {
154	            return LocalDate.parse(raw, ISO);
155	        } catch (DateTimeParseException e) {
156	            throw new InvalidSettingException("Not a date (yyyy-mm-dd): " + raw);
157	        }
158	    }
