245	import java.io.IOException;
246	import java.io.UncheckedIOException;
247	import java.nio.charset.StandardCharsets;
248	import java.nio.file.Files;
249	import java.nio.file.Path;
250	import java.nio.file.StandardOpenOption;
251	import net.officefloor.server.http.HttpHeader;
252	import net.officefloor.server.http.ServerHttpConnection;
253	import java.util.ArrayList;
254	import java.util.Collections;
255	import java.util.List;
256	import java.util.Locale;
257	import java.util.Set;
258	import java.util.regex.Matcher;
259	import java.util.regex.Pattern;
260	import net.officefloor.hq.app.setting.Settings;
261	import org.springframework.beans.factory.ObjectProvider;
262	import org.springframework.beans.factory.annotation.Value;
