265	/**
266	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
267	 * so tests can assert side-effects by reading that file — the second test-assertion channel
268	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
269	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
270	 *
271	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
272	 * SYNC) so a test reads the record immediately.
273	 */
274	@Service
275	public class Audit {
276	
277	    /** The lines that only report figures: they never name the steward a change is made for. */
278	    private static final Set<String> FIGURES = Set.of("ROLLUP", "TOTALS", "ALERT");
279	
280	    private final Path file;
281	    private final ObjectProvider<Settings> settings;
282	
283	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, ObjectProvider<Settings> settings) {
284	        this.file = Path.of(path);
285	        this.settings = settings;
286	    }
287	
288	    /**
289	     * Append one audit record. Tests assert the exact line(s) in the file. A change made by a user the steward role is
290	     * delegated to (for the sheet's today) ends with for=<the steward who delegated>, unless the line only reports figures.
291	     */
292	    public void record(String entry) {
293	        record(entry, null);
294	    }
295	
296	    /**
297	     * Append one audit record about the sheet as it stood on {@code on} (null: the sheet's today): a line by a user the
298	     * steward role was delegated to for that date ends with for=<the steward who delegated>, as {@link #record(String)}.
299	     */
300	    public synchronized void record(String entry, java.time.LocalDate on) {
301	        String delegator = delegator(entry, on);
302	        if (delegator != null) {
303	            entry = entry + " for=" + delegator;
304	        }
305	        try {
306	            Path parent = file.toAbsolutePath().getParent();
307	            if (parent != null) {
308	                Files.createDirectories(parent);
309	            }
310	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
311	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
312	        } catch (IOException e) {
313	            throw new UncheckedIOException(e);
314	        }
315	    }
316	
317	    /** The steward who delegated to the user the line is by, on the line's sheet; null when none did or the line only reports figures. */
318	    private String delegator(String entry, java.time.LocalDate on) {
319	        String[] parts = entry.split(" ", 4);
320	        if (parts.length < 3 || FIGURES.contains(parts[0]) || !parts[1].startsWith("sheet=") || !parts[2].startsWith("by=")) {
321	            return null;
322	        }
323	        String sheetId = parts[1].substring("sheet=".length());
324	        String user = parts[2].substring("by=".length());
325	        return on == null ? settings.getObject().delegator(sheetId, user) : settings.getObject().delegator(sheetId, user, on);
326	    }
327	
328	    /** The signed-in user a write names in its X-User header ("" when it names none). */
329	    public static String user(ServerHttpConnection connection) {
330	        HttpHeader header = connection.getRequest().getHeaders().getHeader("X-User");
331	        return header == null ? "" : header.getValue();
332	    }
333	
334	    /** One record: the event, then sheet=<id> and by=<user>, then the fields, separated by single spaces. */
335	    public static String line(String event, String sheetId, String user, String... fields) {
336	        StringBuilder line = new StringBuilder(event).append(" sheet=").append(sheetId)
337	                .append(" by=").append(user == null ? "" : user.trim());
338	        for (String field : fields) {
339	            line.append(' ').append(field);
340	        }
341	        return line.toString();
342	    }
343	
344	    /**
345	     * The sheet's lines exactly as the file holds them, newest first. With a name (not blank), only the lines about that
346	     * person: those carrying name=<the name> or person=<the name>, compared as names are (case and surrounding spaces ignored).
347	     */
348	    public synchronized List<String> lines(String sheetId, String name) {
349	        String wanted = name == null ? "" : name.trim().toLowerCase(Locale.ROOT);
350	        List<String> all;
351	        try {
352	            all = Files.exists(file) ? Files.readAllLines(file, StandardCharsets.UTF_8) : List.of();
353	        } catch (IOException e) {
354	            throw new UncheckedIOException(e);
355	        }
356	        List<String> lines = new ArrayList<>();
357	        for (String line : all) {
358	            String[] parts = line.split(" ", 3);
359	            if (parts.length >= 2 && parts[1].equals("sheet=" + sheetId)
360	                    && (wanted.isEmpty() || names(line).contains(wanted))) {
361	                lines.add(line);
362	            }
363	        }
364	        Collections.reverse(lines);
365	        return lines;
366	    }
367	
368	    /**
369	     * The sheet's lines about one claim, exactly as the file holds them, newest first: with a number, those carrying
370	     * number=<it>; without one, those carrying no number (a numbered line is about the numbered claim it names) whose
371	     * person= (compared as names are), amount= and date= are all the claim's.
372	     */
373	    public synchronized List<String> claimLines(String sheetId, String number, String person, String amount, String date) {
374	        String wanted = person == null ? "" : person.trim().toLowerCase(Locale.ROOT);
375	        List<String> lines = new ArrayList<>();
376	        for (String line : lines(sheetId, null)) {
377	            java.util.Map<String, List<String>> fields = fields(line);
378	            boolean about = number != null && !number.isBlank()
379	                    ? fields.getOrDefault("number", List.of()).contains(number)
380	                    : !fields.containsKey("number") && fields.getOrDefault("person", List.of()).stream()
381	                            .anyMatch(n -> n.trim().toLowerCase(Locale.ROOT).equals(wanted))
382	                            && fields.getOrDefault("amount", List.of()).contains(amount)
383	                            && fields.getOrDefault("date", List.of()).contains(date);
384	            if (about) {
385	                lines.add(line);
386	            }
387	        }
388	        return lines;
389	    }
390	
391	    /** A line's fields after its event, by key; a value runs up to the next field. */
392	    private static java.util.Map<String, List<String>> fields(String line) {
393	        java.util.Map<String, List<String>> fields = new java.util.HashMap<>();
394	        Matcher m = FIELD.matcher(line);
395	        while (m.find()) {
396	            fields.computeIfAbsent(m.group(1), k -> new ArrayList<>()).add(m.group(2));
397	        }
398	        return fields;
399	    }
400	
401	    private static final Pattern FIELD = Pattern.compile(" ([A-Za-z][\\w-]*)=(.*?)(?= [A-Za-z][\\w-]*=|$)");
402	
403	    /** The values of a line's name= and person= fields, trimmed and lower-cased; a value runs up to the next field. */
404	    private static List<String> names(String line) {
405	        List<String> names = new ArrayList<>();
406	        Matcher m = NAME_FIELD.matcher(line);
407	        while (m.find()) {
408	            names.add(m.group(1).trim().toLowerCase(Locale.ROOT));
409	        }
410	        return names;
411	    }
412	
413	    private static final Pattern NAME_FIELD = Pattern.compile(" (?:name|person)=(.*?)(?= [A-Za-z][\\w-]*=|$)");
414	
415	    /**
416	     * The sheet's activity: for every user (by=) and every event the sheet's lines hold, one line
417	     * {@code <user> <EVENT> <count>}, sorted by user then event.
418	     */
419	    public synchronized List<String> activity(String sheetId) {
420	        java.util.TreeMap<String, java.util.TreeMap<String, Integer>> counts = new java.util.TreeMap<>();
421	        for (String line : lines(sheetId, null)) {
422	            String[] parts = line.split(" ", 4);
423	            String user = parts.length >= 3 && parts[2].startsWith("by=") ? parts[2].substring("by=".length()) : "";
424	            counts.computeIfAbsent(user, k -> new java.util.TreeMap<>()).merge(parts[0], 1, Integer::sum);
425	        }
426	        List<String> activity = new ArrayList<>();
427	        counts.forEach((user, events) -> events.forEach((event, n) -> activity.add(user + " " + event + " " + n)));
428	        return activity;
429	    }
430	
431	    /** Remove the audit file. */
432	    public synchronized void clear() {
433	        try {
434	            Files.deleteIfExists(file);
435	        } catch (IOException e) {
436	            throw new UncheckedIOException(e);
437	        }
438	    }
439	}

import { getJson } from '../../api/http';
import { counts, isOpen } from '../claims/claimsQuery';
import type { Claim, ClaimStatus } from '../claims/claimsQuery';
import type { Person } from '../people/peopleQuery';
import { figure, sumDue } from '../rates/ratesQuery';
import type { Late, Rate } from '../rates/ratesQuery';
import { sheetKey } from '../sheet/sheetQuery';
import type { DatedValue } from '../settings/dated';

/**
 * A sheet's period: a name unique on the sheet, `from` and `to` (yyyy-mm-dd) inclusive. Periods never overlap.
 * A closed period's due-total was fixed when it was closed (`closedTotal`; null while open), and so was each
 * person's due-total for it (`personTotals`, by person id; empty while open, and a person added later has none), and
 * each person's carried figure for it (`personCarried`, the same way; a period fixed before carried figures were has none).
 * A soft-closed period (`soft`, not `closed`) has its figures fixed the same way, while its claims can still change.
 * Each person's pasted opening balance for it (`personOpenings`, by person id; none is 0.00) is part of their carried figure.
 */
export type Period = {
  name: string;
  from: string;
  to: string;
  closed: boolean;
  closedTotal: string | null;
  personTotals: Record<string, string>;
  personCarried: Record<string, string>;
  soft: boolean;
  /** How many OPEN or PENDING claims each person may have in the period; null for no cap. */
  cap: number | null;
  personOpenings: Record<string, string>;
  /** A locked period cannot be reopened; only a steward locks and unlocks it. */
  locked: boolean;
};

/** Whether the period's figures are fixed: it is closed or soft-closed. */
export const isFixed = (period: Period) => period.closed || period.soft;

/** Under the sheet's key, so re-loading the sheet re-reads its periods. */
export const periodsKey = (sheetId: string) => [...sheetKey(sheetId), 'periods'] as const;

/** The sheet's periods, by from-date. */
export const periodsQuery = (sheetId: string) => ({
  queryKey: periodsKey(sheetId),
  queryFn: () => getJson<Period[]>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`),
});

/** The period whose dates contain the date (yyyy-mm-dd), or undefined when none does. A claim's period is the one containing its due-by. */
export function periodOf(periods: Period[], date: string): Period | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}

/**
 * The claim's status at the end of the day `on` (yyyy-mm-dd), as its log records it: the last status logged on or
 * before it, DRAFT (counting nowhere) when it was added after. A claim with no log has its status now.
 */
export function statusOn(c: Claim, on: string): ClaimStatus {
  const log = c.log ?? [];
  if (log.length === 0) return c.status;
  let status: ClaimStatus = 'DRAFT';
  for (const line of log) {
    const m = /^(\S+) by .* on (\d{4}-\d{2}-\d{2}) due=\S*$/.exec(line);
    if (m && m[2] <= on) status = m[1] as ClaimStatus;
  }
  return status;
}

/**
 * A person's due-total for a period: the figures (as shown now) of their claims in it (by due-by) that counted by the
 * status they had at the end of its last day. A hold leaves out only a claim that is open now. While the period is
 * closed or soft-closed it is the figure fixed then (0.00 for a person added since).
 */
export function personPeriodDue(
  period: Period,
  person: Person,
  claims: Claim[],
  people: Person[],
  rates: Rate[],
  floor: DatedValue[],
  late: Late,
): string {
  if (isFixed(period)) return period.personTotals[String(person.id)] ?? '0.00';
  return sumDue(
    claims
      .filter(
        (c) =>
          c.personId === person.id &&
          period.from <= c.dueBy &&
          c.dueBy <= period.to &&
          counts({ ...c, status: statusOn(c, period.to), held: c.held && isOpen(c) }, isOpen(c) ? people : [], late.today),
      )
      .map((c) => figure(c, rates, person, floor, late)),
  );
}

/**
 * A person's carried figure for a period: the figures (as shown now) of their claims that count which belong (by due-by)
 * to a period ending before this one starts and were still OPEN or PENDING at the end of its last day, by their log,
 * and their opening balance for it. While the period is closed or soft-closed it is the figure fixed then (0.00 for a person added since).
 */
export function personPeriodCarried(
  period: Period,
  periods: Period[],
  person: Person,
  claims: Claim[],
  people: Person[],
  rates: Rate[],
  floor: DatedValue[],
  late: Late,
): string {
  if (isFixed(period)) {
    const id = String(person.id);
    if (id in period.personCarried) return period.personCarried[id];
    if (!(id in period.personTotals)) return '0.00';
  }
  const opening = period.personOpenings?.[String(person.id)] ?? '0.00';
  return sumDue([
    opening,
    ...claims
      .filter((c) => {
        if (c.personId !== person.id) return false;
        const own = periodOf(periods, c.dueBy);
        if (!own || own.to >= period.from) return false;
        const status = statusOn(c, period.to);
        return (status === 'OPEN' || status === 'PENDING') && counts({ ...c, status, held: c.held && isOpen(c) }, isOpen(c) ? people : [], late.today);
      })
      .map((c) => figure(c, rates, person, floor, late)),
  ]);
}

/** A period's due-total: its people's due-totals for it added up. */
export function periodDue(period: Period, claims: Claim[], people: Person[], rates: Rate[], floor: DatedValue[], late: Late): string {
  return sumDue(people.map((p) => personPeriodDue(period, p, claims, people, rates, floor, late)));
}

/**
 * A period's classic due-total: the figures (as shown now) of its claims (by due-by) that count by their status now
 * (OPEN, SETTLED and PENDING; a hold or retirement leaves out an open claim as everywhere else). While the period is
 * closed or soft-closed it is the figure fixed then.
 */
export function classicPeriodDue(period: Period, claims: Claim[], people: Person[], rates: Rate[], floor: DatedValue[], late: Late): string {
  if (isFixed(period)) return period.closedTotal ?? sumDue(Object.values(period.personTotals));
  return sumDue(
    claims
      .filter((c) => period.from <= c.dueBy && c.dueBy <= period.to && counts(c, people, late.today))
      .map((c) => figure(c, rates, people.find((p) => p.id === c.personId), floor, late)),
  );
}
