31	/** A clone made: the sheet cloned ({@code fromSheetId}) and the sheet it was cloned to ({@code toSheetId}). */
32	public record ClonedSheet(String fromSheetId, String toSheetId) {
33	}
34	/** The body of a clone of a sheet: the id of the (never used) sheet to clone it to. */
35	public record CloneRequest(String toSheetId) {
36	}
37	/** The clone as the screen sees it: the id of the sheet it was cloned to. */
38	public record CloneResponse(String toSheetId) {
39	    public static CloneResponse from(ClonedSheet cloned) {
40	        return new CloneResponse(cloned.toSheetId());
41	    }
42	}
43	public class CloneSheet {
44	    // Only a steward (a delegation included) clones the sheet, and only to a sheet id never used. Each numbered claim
45	    // takes the next number of the clone, in the order the originals were opened (the sheet's today when each was first
46	    // opened, then the order they were added to the clone).
47	    public void clone(@PathVariable("sheetId") String sheetId, @RequestBody(required = false) CloneRequest body,
48	            Settings settings, Sheets sheets, SheetClones clones, Claims claims, Periods periods,
49	            ServerHttpConnection connection, Out<ClonedSheet> clonedOut) throws SheetCloneRefusedException {
50	        String from = sheetId.trim();
51	        if (!Settings.STEWARD.equals(settings.role(from, Audit.user(connection).trim()))) {
52	            throw new SheetCloneRefusedException("Only a steward can clone the sheet.");
53	        }
54	        String to = body == null || body.toSheetId() == null ? "" : body.toSheetId().trim();
55	        if (to.isEmpty()) {
56	            throw new SheetCloneRefusedException("Give the id of the sheet to clone to.");
57	        }
58	        if (to.equals(from) || sheets.exists(to) || clones.used(to)) {
59	            throw new SheetCloneRefusedException("The sheet " + to + " is already used: a clone goes only to a new sheet.");
60	        }
61	        Map<Long, Long> copied = clones.copy(from, to, sheets.find(from).today());
62	        // The numbered claims in the order they were opened, each given the next number of the clone.
63	        Map<Long, LocalDate> opened = claims.openedOn(from);
64	        Map<Long, Claim> originals = new HashMap<>();
65	        claims.list(from).forEach(c -> originals.put(c.id(), c));
66	        List<Long> numbered = new ArrayList<>(copied.keySet().stream()
67	                .filter(id -> originals.get(id).number() != null).toList());
68	        numbered.sort(Comparator.<Long, LocalDate>comparing(id -> opened.getOrDefault(id, originals.get(id).date()))
69	                .thenComparingLong(copied::get));
70	        LocalDate numberingFrom = settings.periodNumberingFrom(to);
71	        boolean byPeriod = numberingFrom != null && !sheets.today(to).isBefore(numberingFrom);
72	        Map<String, String> renumbered = new HashMap<>();
73	        Map<Long, String> numbers = new HashMap<>();
74	        for (Long id : numbered) {
75	            Claim claim = originals.get(id);
76	            String scope = null;
77	            if (byPeriod) {
78	                Period period = periods.on(to, claim.dueBy());
79	                scope = period == null ? "" : period.name();
80	            }
81	            String number = claims.number(to, scope, claim.dueBy() == null ? claim.date() : claim.dueBy());
82	            numbers.put(copied.get(id), number);
83	            renumbered.put(claim.number(), number);
84	        }
85	        clones.number(copied, originals, numbers, renumbered);
86	        clonedOut.set(new ClonedSheet(from, to));
87	    }
88	}
