177	/** Copies a whole sheet to a new sheet id, for a clone. */
178	@Repository
179	public class SheetClones {
180	    /** The tables kept per sheet (by sheet_id) whose rows show a sheet has been used. */
181	    private static final List<String> SHEET_TABLES = List.of("person", "claim", "setting", "setting_from", "rate",
182	            "sheet_role", "period", "holiday", "void_reason", "claim_template", "pool", "crew");
183	    private final JdbcTemplate jdbc;
184	    public SheetClones(JdbcTemplate jdbc) {
185	        this.jdbc = jdbc;
186	    }
187	    /** Whether anything is stored for the sheet. */
188	    public boolean used(String sheetId) {
189	        for (String table : SHEET_TABLES) {
190	            Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM " + table + " WHERE sheet_id = ?", Integer.class, sheetId);
191	            if (n != null && n > 0) {
192	                return true;
193	            }
194	        }
195	        return false;
196	    }
197	    /**
198	     * Copy the sheet {@code from} to the empty sheet {@code to}, which takes {@code today}: its settings, roles, rates,
199	     * holidays, void reasons, templates, people (grades, terms, contacts, tags, aliases, holds, retirements, patrons), pools, crews,
200	     * periods (all open) and claims (status, frozen figures, dates, notes, tags, references, logs; unnumbered and unbound by
201	     * any statement, listed in the order they were). Returns each copied claim's id here by its id on {@code from}, in the
202	     * order they were added to the clone.
203	     */
204	    public Map<Long, Long> copy(String from, String to, LocalDate today) {
205	        // The sheet's own row first, so every copied row's history is dated by the clone's today.
206	        jdbc.update("INSERT INTO sheet (id, today_date, archived) VALUES (?, ?, FALSE)", to, today);
