400	public class ValidateToday {
401	    private static final DateTimeFormatter ISO = DateTimeFormatter.ofPattern("uuuu-MM-dd")
402	            .withResolverStyle(ResolverStyle.STRICT);
403	    // Blank takes the default: the real date.
404	    public LocalDate validate(@RequestBody TodayRequest body) throws InvalidTodayException {
405	        String raw = body == null || body.today() == null ? "" : body.today().trim();
