433	public class CancelStatement {
434	    // Only a steward cancels a person's last statement. Every claim it bound is live again: a statement
435	    // rebinds all of the person's counting claims, so the figures an earlier statement bound are gone and
436	    // are not restored.
437	    public void cancel(@Val Person person, Claims claims, Settings settings, Statements statements,
438	            ServerHttpConnection connection, Out<CancelledStatement> cancelledOut) throws StatementRefusedException {
439	        if (!Settings.STEWARD.equals(settings.role(person.sheetId(), Audit.user(connection).trim()))) {
440	            throw new StatementRefusedException("Only a steward may cancel a statement.");
441	        }
442	        statements.lock(person.id());
443	        CancelledStatement cancelled = statements.removeLast(person.sheetId(), person.id());
444	        if (cancelled == null) {
445	            throw new StatementRefusedException(person.name() + " has no statement to cancel.");
446	        }
447	        claims.bind(person.sheetId(), person.id(), java.util.Map.of());
448	        cancelledOut.set(cancelled);
449	    }
450	}
