539	public class TakeStatement {
540	    // Records the person's due-total now (a deferred claim counts in none and is left unbound) (held to the sheet's cap) and binds each of their counting claims (their open claims within a hold and not bound do not count) to its figure now;
541	    // the rest of their claims are left unbound. Each claim is bound to its due as shown, late charge and floor included, so
542	    // while bound it no longer follows the sheet's today; a claim already bound keeps the figure it was bound to.
543	    // Taken as of a date (on or before the sheet's today), it is worked out from the person and their claims as they stood at
544	    // the end of that date, with that date for the sheet's today; it binds those claims still theirs, and records that date.
545	    public void take(@Val Person person, @Val StatementAsOf asOf, Claims claims, People people, Rates rates, Settings settings,
546	            Sheets sheets, Statements statements, Out<Statement> statementOut) throws StatementRefusedException {
547	        statements.lock(person.id());
548	        LocalDate today = sheets.today(person.sheetId());
549	        Stated stated;
550	        if (asOf.date() == null) {
551	            stated = stated(person, today, claims, rates, settings);
552	        } else {
553	            if (asOf.date().isAfter(today)) {
554	                throw new StatementRefusedException("A statement cannot be taken as of a date after the sheet's today.");
555	            }
556	            stated = AsOf.on(asOf.date(), () -> {
557	                Person then = people.find(person.sheetId(), person.id());
558	                return then == null ? null : stated(then, asOf.date(), claims, rates, settings);
559	            });
560	            if (stated == null) {
561	                throw new StatementRefusedException(person.name() + " was not on the sheet on " + asOf.date() + ".");
562	            }
563	            // A claim since moved to another person is no longer theirs to bind.
564	            Set<Long> theirs = claims.list(person.sheetId()).stream().filter(c -> c.personId() == person.id())
565	                    .map(Claim::id).collect(Collectors.toSet());
566	            stated.figures().keySet().retainAll(theirs);
567	        }
568	        claims.bind(person.sheetId(), person.id(), stated.figures());
569	        Statement statement = new Statement(person.sheetId(), person.id(), stated.dueTotal(), stated.figures().size(),
570	                asOf.date() == null ? today : asOf.date(), asOf.date());
571	        statements.add(statement);
572	        statementOut.set(statement);
573	    }
574	    /** What a statement binds (each counting claim's figure, by id) and records (the due-total). */
575	    private record Stated(Map<Long, BigDecimal> figures, String dueTotal) {
576	    }
577	    /** The person's statement with {@code today} as the sheet's today. */
578	    private static Stated stated(Person person, LocalDate today, Claims claims, Rates rates, Settings settings) {
579	        Map<Long, BigDecimal> figures = new LinkedHashMap<>();
580	        BigDecimal total = BigDecimal.ZERO.setScale(2);
581	        for (Claim claim : claims.list(person.sheetId())) {
582	            if (claim.personId() == person.id()
583	                    && (claim.status() == ClaimStatus.SETTLED || (claim.status().isOpen() && Rollup.counts(claim, person, today)))) {
584	                BigDecimal due = due(claim, person, today, rates, settings);
585	                figures.put(claim.id(), due);
586	                if (due != null) {
587	                    total = total.add(due);
588	                }
589	            }
590	        }
591	        // With no rate today and no figure, the due-total is n/a.
592	        boolean none = rates.on(person.sheetId(), person.gradeOn(today), today) == null
593	                && figures.values().stream().allMatch(Objects::isNull);
594	        return new Stated(figures, none ? "n/a" : settings.capped(person.sheetId(), total).toPlainString());
595	    }
596	    /**
597	     * The claim's due as shown with {@code today} as the sheet's today (null when it has none): a settled claim's frozen due,
598	     * otherwise the due the last statement bound it to, otherwise its amount times its person's grade's rate on its date,
599	     * rounded by the policy date, raised to the floor, with its late charge on {@code today} (worked out on the floored figure) added on top.
600	     */
601	    private static BigDecimal due(Claim claim, Person person, LocalDate today, Rates rates, Settings settings) {
602	        if (claim.settledDue() != null) {
603	            return claim.settledDue();
604	        }
605	        if (claim.stated()) {
606	            return claim.statedDue();
607	        }
608	        BigDecimal rate = rates.forClaim(claim, person.gradeOn(claim.date()));
609	        return settings.withLate(claim, settings.live(claim, rate), today);
610	    }
611	}
612	public class ValidateStatement {
613	    private static final DateTimeFormatter ISO = DateTimeFormatter.ofPattern("uuuu-MM-dd")
614	            .withResolverStyle(ResolverStyle.STRICT);
