/** Due-totals compare as numbers, lowest first, with n/a last. */
export function compareDue(a: string, b: string): number {
  const x = Number(a);
  const y = Number(b);
  const xa = Number.isNaN(x);
  const ya = Number.isNaN(y);
  if (xa || ya) return xa === ya ? 0 : xa ? 1 : -1;
  return x - y;
}
